verus! {
    /// Given a vector of non‐empty `Vec<char>`, returns a `Vec<char>` whose
    /// i‐th element is the last character of the i‐th inner vector.
    fn extract_rear_chars(s: &Vec<Vec<char>>) -> Vec<char>
        requires
            // every inner sequence is non‐empty
            forall |i: int|
                0 <= i && i < s.len() as int ==>
                s[i as usize].len() > 0,
        ensures
            // the result has the same length as the outer sequence
            result.len() == s.len(),
        ensures
            // for each i, result[i] is the last character of s[i]
            forall |i: int|
                0 <= i && i < s.len() as int ==>
                result[i as usize] ==
                s[i as usize][s[i as usize].len() - 1],
    {
        let mut result: Vec<char> = Vec::new();
        let mut idx: usize = 0;
        // iterate over all the inner sequences
        while idx < s.len()
            invariant
                // we have processed exactly idx elements so far
                idx <= s.len(),
                result.len() == idx,
                // for all j < idx, result[j] = last character of s[j]
                forall |j: int|
                    0 <= j && j < idx as int ==>
                    result[j as usize] ==
                    s[j as usize][s[j as usize].len() - 1],
            decreases s.len() - idx,
        {
            let inner = &s[idx];
            let last_idx = inner.len() - 1;
            let c = inner[last_idx];
            result.push(c);
            idx = idx + 1;
        }
        result
    }
}

